#include <iostream>
using namespace std;

int main() {
    int a = 17;
    int b = 5;
    cout << "a + b = " << a + b << endl;
    cout << "a - b = " << a - b << endl;
    cout << "a * b = " << a * b << endl;
    cout << "a / b = " << a / b << endl;
    cout << "a % b = " << a % b << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int x = 5;
    int y = x++;
    cout << "x = " << x << ", y = " << y << endl;
    int z = ++x;
    cout << "x = " << x << ", z = " << z << endl;
    return 0;
}

#include <iostream>
using namespace std;

